const setupLinkRoute=p.match(/^\/api\/school-portal-accounts\/([^/]+)\/reset-link$/);if(setupLinkRoute&&r.method==="POST"){const s=await auth(r,env);if(!s.school_id||!["headmaster","admin"].includes(s.role))return err(403,"School administrator access required.");const target=await env.DB.prepare("SELECT u.id,u.email,m.role FROM users u JOIN school_memberships m ON m.user_id=u.id WHERE u.id=? AND m.school_id=? AND m.status='active' AND m.role IN ('student','parent')").bind(setupLinkRoute[1],s.school_id).first();if(!target)return err(404,"Active student or parent account not found.");const token=b64(crypto.getRandomValues(new Uint8Array(32))),expires=new Date(Date.now()+86400000).toISOString();await env.DB.prepare("INSERT INTO password_reset_tokens(id,user_id,school_id,token_hash,identity_key,expires_at) VALUES(?,?,?,?,?,?)").bind(uid(),target.id,s.school_id,await sha(token),target.email,expires).run();const origin=r.headers.get("Origin")||"",allowed=(env.ALLOWED_ORIGINS||"").split(",").map(x=>x.trim()),base=String(env.APP_ORIGIN||(allowed.includes(origin)?origin:"")).replace(/\/$/,"");if(!base)return err(503,"Set APP_ORIGIN or allow the frontend origin in ALLOWED_ORIGINS to generate password setup links.");return j({url:base+"/reset-password?token="+encodeURIComponent(token),expires_at:expires,role:target.role});}
