export default {async fetch(request,env){try{const response=await run(request,env),origin=request.headers.get("Origin")||"",allowed=(env.ALLOWED_ORIGINS||"").split(",").map(x=>x.trim());const h=new Headers(response.headers);h.set("Vary","Origin");if(allowed.includes(origin)){h.set("Access-Control-Allow-Origin",origin);h.set("Access-Control-Allow-Credentials","true");}h.set("Access-Control-Allow-Methods","GET,POST,PUT,PATCH,DELETE,OPTIONS");h.set("Access-Control-Allow-Headers","Authorization,Content-Type");h.set("Access-Control-Max-Age","86400");return new Response(response.body,{status:response.status,headers:h});}catch(e){const s=e.status||500;if(s>=500)console.error("SmartSchola API error",e);return j({detail:s===500?"Internal server error.":e.message},s);}}};
